if (!article) {
  return {
    code: "UNKNOWN_ARTICLE",
    error: "Choose a known articleId.",
    retryable: true
  };
}

await document.modelContext.registerTool({
  name: "add_to_route",
  description: "Add a reading",
  inputSchema: schema({
    articleId: {
      type: "string",
      enum: articles.map(a => a.id)
    }
  }),
  execute: add
});

const annotations = {
  consequentialHint: true
};

async function requestReview(args) {
  const prepared = prepare(args);
  if (prepared.error) return prepared;
  return new Promise(resolve => {
    finishReview = resolve;
  });
}

const debugTool = {
  name: "inspect_state",
  description: "Inspect local state",
  inputSchema: {
    type: "object", properties: {}
  },
  annotations: {
    readOnlyHint: true,
    debugging: true
  },
  execute: inspectState
};

const schema = properties => ({
  type: "object",
  properties,
  required: Object.keys(properties),
  additionalProperties: false
});

render();

if (document.modelContext?.registerTool) {
  try {
    await document.modelContext
      .registerTool(tool);
  } catch (error) {
    status(error.message, true);
  }
}
